async function main() {
  console.log(`Seed-expand: ${watches.length} watches to upsert across multiple brands...\n`);

  // Gather unique brands
  const brands = [...new Set(watches.map(w => w.brand))];
  console.log(`Brands (${brands.length}): ${brands.join(', ')}\n`);

  let created = 0;
  let updated = 0;
  let errors = 0;

  for (let i = 0; i < watches.length; i++) {
    const w = watches[i];
    const slug = makeSlug(`${w.brand} ${w.model}`);
    const apiId = `seed-expand-${String(i + 1).padStart(3, '0')}`;

    const data = {
      apiId,
      brand: w.brand,
      model: w.model,
      reference: w.reference ?? null,
      year: w.year ?? null,
      caseDiameter: w.caseDiameter ?? null,
      caseThickness: w.caseThickness ?? null,
      waterResistance: w.waterResistance ?? null,
      movement: w.movement ?? null,
      caliber: w.caliber ?? null,
      powerReserve: w.powerReserve ?? null,
      caseMaterial: w.caseMaterial ?? null,
      bezelMaterial: w.bezelMaterial ?? null,
      crystal: w.crystal ?? null,
      frequency: w.frequency ?? null,
      jewels: w.jewels ?? null,
      cosc: w.cosc ?? false,
      priceRange: w.priceRange ?? 3,
      brandTier: w.brandTier ?? 3,
      style: w.style ?? 'sport',
      slug,
    };

    try {
      const existing = await prisma.watch.findUnique({ where: { slug } });
      await prisma.watch.upsert({
        where: { slug },
        update: { ...data, slug: undefined, apiId: undefined },
        create: data,
      });
      if (existing) {
        updated++;
      } else {
        created++;
      }
      if ((i + 1) % 50 === 0) {
        console.log(`  Progress: ${i + 1}/${watches.length} watches processed`);
      }
    } catch (err) {
      console.error(`  Error upserting ${slug}: ${err.message}`);
      errors++;
    }
  }

  console.log(`\n=== Seed Expand Complete ===`);
  console.log(`Created: ${created}`);
  console.log(`Updated: ${updated}`);
  console.log(`Errors: ${errors}`);

  const totalWatches = await prisma.watch.count();
  console.log(`\nTotal watches in database: ${totalWatches}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
